const store  = flow.get('offers') || {};   // src:id  -> offer
const keys   = flow.get('seenKeys') || {}; // company|title -> first source that reported it
const marks  = flow.get('marks') || {};    // per-source watermark
const first  = Object.keys(store).length === 0;
const now    = Date.now();
const fresh  = [];
const added  = [];                         // every newly stored offer -> output 2 (database)

// titles whose stack we don't want notified (still stored, so they never resurface)
const RE = /(?:^|[^a-z0-9+#])(\.?net|dotnet|go|golang|java)(?![a-z0-9+#.])/i;

// Cut DB if too big
const MAX = 10000;
const stored = Object.keys(store);
if (stored.length > MAX) {
    stored.sort((a, b) => store[a].firstSeen - store[b].firstSeen)
          .slice(0, stored.length - MAX)
          .forEach(id => { delete keys[store[id].key]; delete store[id]; });
}

// ---- TEST: forget the 3 newest offers of one source ------------------------
// const SRC = 'eldorado';
// const top = Object.values(store).filter(o => o.src === SRC)
//                   .sort((a, b) => b.sortVal - a.sortVal).slice(0, 3);
// top.forEach(o => { delete keys[o.key]; delete store[o.src + ':' + o.id]; });
// marks[SRC] = Math.max(...Object.values(store).filter(o => o.src === SRC).map(o => o.sortVal));
// flow.set('offers', store); flow.set('seenKeys', keys); flow.set('marks', marks);
// node.warn('forgot ' + top.map(o => o.id).join(', ') + ' | ' + SRC + ' mark now ' + marks[SRC]);
// return null;
// ---------------------------------------------------------------------------

const list    = msg.payload || [];
const src     = list.length ? list[0].src : null;
const seeding = src !== null && marks[src] === undefined;  // first sight of this source
const mark    = marks[src] || 0;
let highest = mark, bubbled = 0, dupes = 0, excluded = 0;

list.forEach(o => {
    if (!o || !o.id) return;
    const ref = o.src + ':' + o.id;

    if (o.sortVal > highest) highest = o.sortVal;

    if (store[ref]) { store[ref].lastSeen = now; return; }

    store[ref] = {
        src: o.src, id: o.id, key: o.key,
        title: o.title, company: o.company,
        seniority: o.seniority, remote: o.remote, url: o.url,
        sortVal: o.sortVal, firstSeen: now, lastSeen: now
    };
    added.push(store[ref]);

    if (o.sortVal <= mark)     { bubbled++;  return; }   // older than watermark
    if (keys[o.key])           { dupes++;    return; }   // already seen via other source
    if (RE.test(o.title || '')){ excluded++; return; }   // wrong stack

    keys[o.key] = o.src;
    fresh.push(store[ref]);
});

if (src) marks[src] = highest;
flow.set('offers', store);
flow.set('seenKeys', keys);
flow.set('marks', marks);
node.status({ text: `${src}: ${seeding ? 'SEEDED' : fresh.length + ' new'}, ${bubbled} old, ${dupes} dup, ${excluded} excl | ${Object.keys(store).length} stored` });

// output 2: everything newly stored goes to the database, seeding runs included
const db = added.length ? { payload: added } : null;

// a source's first run only seeds - never queue its whole first page
if (first || seeding) return [null, db];

// queue everything new; flush_queue decides when it actually goes out
const queue = flow.get('queued') || [];
fresh.forEach(o => queue.push(o));
flow.set('queued', queue);

if (flow.get('paused')) {
    node.status({ text: `${src}: ${fresh.length} queued (muted), ${queue.length} waiting` });
    return [null, db];
}

return [fresh.length ? { manual: false } : null, db];

const WANTED_CITY = /warszaw/i;

function decodeFlight(html) {
    let flight = '';
    const re = /self\.__next_f\.push\(\[1,("(?:\\.|[^"\\])*")\]\)/g;
    let m;
    while ((m = re.exec(html)) !== null) {
        try { flight += JSON.parse(m[1]); } catch (e) { /* skip bad chunk */ }
    }
    return flight;
}

function sliceArray(flight, key) {
    const i = flight.indexOf(key);
    if (i === -1) return null;
    const start = i + key.length - 1;
    let depth = 0, inStr = false, esc = false;
    for (let k = start; k < flight.length; k++) {
        const c = flight[k];
        if (inStr) {
            if (esc) esc = false;
            else if (c === '\\') esc = true;
            else if (c === '"') inStr = false;
            continue;
        }
        if (c === '"') inStr = true;
        else if (c === '[') depth++;
        else if (c === ']' && --depth === 0) return flight.slice(start, k + 1);
    }
    return null;
}

function isWarsawOrRemote(job) {
    const modes = job.workModes || [];
    const cities = job.cities || [];

    if (modes.includes('remote')) return true;     // remote -> city irrelevant
    if (cities.length === 0) return true;          // no pin icon -> keep
    return cities.some(c => WANTED_CITY.test(c));  // hybrid/office -> must be Warszawa
}

const flight = decodeFlight(msg.payload || '');
const raw = sliceArray(flight, '"jobs":[');
if (!raw) {
    node.error('jobs anchor not found - site format changed', msg);
    return null;
}

let jobs;
try { jobs = JSON.parse(raw); }
catch (e) { node.error('jobs JSON parse failed: ' + e.message, msg); return null; }

const keep = jobs.filter(isWarsawOrRemote);
node.status({ fill: 'green', shape: 'dot', text: keep.length + '/' + jobs.length + ' kept' });

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
msg.payload = keep.map(j => ({
    src: 'eldorado',
    id: String(j.id),
    sortVal: j.id,                               // insert counter = import order
    key: norm((j.company || {}).name) + '|' + norm(j.title),
    title: j.title,
    company: (j.company || {}).name,
    seniority: j.seniority || 'unknown',
    remote: (j.workModes || []).includes('remote') ? 'yes' : 'no',
    url: 'https://czyjesteldorado.pl/praca/' + j.id + '-' + j.slug
}));
return msg;

// justjoin candidate-api -> same payload shape as parse_offers
// http request node must use  Return: a parsed JSON object
const WANTED_CITY  = /warszaw/i;
const WANTED_SKILL = /react/i;

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');

function hasSkill(o) {
    const skills = [].concat(o.requiredSkills || [], o.niceToHaveSkills || []);
    if (skills.some(s => WANTED_SKILL.test(s && s.name ? s.name : s))) return true;
    return WANTED_SKILL.test(o.title || '');
}

function inWarsawOrRemote(o) {
    if (o.workplaceType === 'remote') return true;
    if (WANTED_CITY.test(o.city || '')) return true;
    return (o.locations || []).some(l => WANTED_CITY.test(l.city || ''));
}

// accept either a parsed object or a raw JSON string
let body = msg.payload;
if (typeof body === 'string') {
    try { body = JSON.parse(body); }
    catch (e) {
        node.error('justjoin api: reply is not JSON (status ' + msg.statusCode + '): ' +
                   String(msg.payload).slice(0, 120), msg);
        return null;
    }
}

const offers = body && Array.isArray(body.data) ? body.data : null;
if (!offers) {
    node.error('justjoin api: no data array (status ' + msg.statusCode + ', keys: ' +
               (body && typeof body === 'object' ? Object.keys(body).join(',') : typeof body) + ')', msg);
    return null;
}

const keep = offers.filter(o => hasSkill(o) && inWarsawOrRemote(o));
node.status({ fill: 'green', shape: 'dot', text: keep.length + '/' + offers.length + ' kept' });

msg.payload = keep.map(o => ({
    src:       'justjoin',
    id:        o.slug,
    sortVal:   Date.parse(o.publishedAt),   // exact chronological order
    key:       norm(o.companyName) + '|' + norm(o.title),
    title:     o.title,
    company:   o.companyName,
    seniority: o.experienceLevel || 'unknown',
    remote:    o.workplaceType === 'remote' ? 'yes' : 'no',
    url:       'https://justjoin.it/job-offer/' + o.slug
}));
return msg;

// solid.jobs public API -> same payload shape as the other parsers
// http request node: Return = a parsed JSON object
const WANTED_CITY  = /warszaw/i;
const WANTED_SKILL = /react/i;

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');

function hasSkill(o) {
    if ((o.skills || []).some(s => WANTED_SKILL.test(s && s.name ? s.name : s))) return true;
    return WANTED_SKILL.test(o.title || '');
}

function inWarsawOrRemote(o) {
    if (o.isRemote) return true;
    return (o.locations || []).some(c => WANTED_CITY.test(c));
}

let body = msg.payload;
if (typeof body === 'string') {
    try { body = JSON.parse(body); }
    catch (e) {
        node.error('solid.jobs: reply is not JSON (status ' + msg.statusCode + '): ' +
                   String(msg.payload).slice(0, 120), msg);
        return null;
    }
}

const offers = body && Array.isArray(body.jobs) ? body.jobs : null;
if (!offers) {
    node.error('solid.jobs: no jobs array (status ' + msg.statusCode + ', keys: ' +
               (body && typeof body === 'object' ? Object.keys(body).join(',') : typeof body) + ')', msg);
    return null;
}

const keep = offers.filter(o => hasSkill(o) && inWarsawOrRemote(o));
node.status({ fill: 'green', shape: 'dot', text: keep.length + '/' + offers.length + ' kept' });

msg.payload = keep.map(o => ({
    src:       'solidjobs',
    id:        o.jobOfferKey,
    sortVal:   Date.parse(o.validFrom),
    key:       norm(o.company) + '|' + norm(o.title),
    title:     o.title,
    company:   o.company,
    seniority: (o.experienceLevel || 'unknown').toLowerCase(),
    remote:    o.isRemote ? 'yes' : 'no',
    url:       o.url
}));
return msg;

// builtin.com job cards -> same payload shape as the other parsers
// http request node: Return = a UTF-8 string
// The URL already filters remote + Poland + freshness; we only re-check the tech.
const WANTED_SKILL = /react/i;
const CHECK_SKILL  = true;     // set false to trust the site's search= filter

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };
const strip = s => String(s || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&([a-z]+);/gi, (m, n) => ENT[n.toLowerCase()] !== undefined ? ENT[n.toLowerCase()] : m)
    .replace(/\s+/g, ' ').trim();

const html = msg.payload || '';
if (typeof html !== 'string' || html.indexOf('data-id="job-card"') === -1) {
    node.error('builtin: no job cards found (status ' + msg.statusCode +
               ', ' + String(html).length + ' bytes) - blocked or markup changed', msg);
    return null;
}

// split the page into one chunk per card
const chunks = html.split(/<div id="job-card-(?=\d)/).slice(1);

const offers = [];
for (const c of chunks) {
    const id = (c.match(/^(\d+)/) || [])[1];
    if (!id) continue;

    const a = c.match(/data-id="job-card-title"[^>]*>([\s\S]*?)<\/a>/);
    const title = strip(a && a[1]);

    const co = c.match(/data-id="company-title"[\s\S]*?<span[^>]*>([\s\S]*?)<\/span>/);
    const company = strip(co && co[1]);

    const href = (c.match(/href="(\/job\/[^"]+)"/) || [])[1];
    const age  = strip((c.match(/>([^<]*(?:Minutes?|Hours?|Days?|Yesterday|Today)[^<]*)</i) || [])[1]);
    const mode = strip((c.match(/>((?:In-Office or )?Remote|In-Office|Hybrid)</i) || [])[1]);

    if (!title || !href) continue;
    if (CHECK_SKILL && !WANTED_SKILL.test(title)) continue;

    offers.push({
        src:       'builtin',
        id:        id,
        sortVal:   Number(id),          // ascending job id = insert order
        key:       norm(company) + '|' + norm(title),
        title:     title,
        company:   company || 'unknown',
        seniority: /senior|lead|principal/i.test(title) ? 'senior'
                 : /junior|intern|gradu/i.test(title)   ? 'junior'
                 : 'unknown',
        remote:    /^remote$/i.test(mode) ? 'yes' : 'no',
        posted:    age,
        url:       'https://builtin.com' + href
    });
}

node.status({ fill: 'green', shape: 'dot', text: offers.length + '/' + chunks.length + ' kept' });
msg.payload = offers;
return msg;

// bulldogjob.pl listing (Next.js __NEXT_DATA__) -> shared payload shape
// http request node: Return = a UTF-8 string
const WANTED_CITY = /warszaw|warsaw/i;

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');

const html = msg.payload || '';
const m = String(html).match(/<script id="__NEXT_DATA__" type="application\/json"[^>]*>([\s\S]*?)<\/script>/);
if (!m) {
    node.error('bulldog: __NEXT_DATA__ not found (status ' + msg.statusCode +
        ', ' + String(html).length + ' bytes)', msg);
    return null;
}

let jobs;
try {
    jobs = JSON.parse(m[1]).props.pageProps.jobs;
} catch (e) {
    node.error('bulldog: cannot read props.pageProps.jobs: ' + e.message, msg);
    return null;
}
if (!Array.isArray(jobs)) {
    node.error('bulldog: jobs is not an array - page shape changed', msg);
    return null;
}

function inWarsawOrRemote(j) {
    if (j.remote === true) return true;
    // city may be "", one city, or "Krakow, London, Barcelona"
    return String(j.city || '').split(',').some(c => WANTED_CITY.test(c.trim()));
}

const keep = jobs.filter(inWarsawOrRemote);
node.status({ fill: 'green', shape: 'dot', text: keep.length + '/' + jobs.length + ' kept' });

msg.payload = keep.map(j => {
    const num = Number(String(j.id).split('-')[0]);   // ascending insert counter
    return {
        src: 'bulldog',
        id: String(j.id),
        sortVal: Number.isFinite(num) ? num : 0,
        key: norm(j.company && j.company.name) + '|' + norm(j.position),
        title: j.position,
        company: (j.company && j.company.name) || 'unknown',
        seniority: j.experienceLevel || 'unknown',
        remote: j.remote === true ? 'yes' : 'no',
        url: 'https://bulldogjob.pl/companies/jobs/' + j.id
    };
});
return msg;

// nofluffjobs.com listing (Angular serverApp-state) -> shared payload shape
// http request node: Return = a UTF-8 string
const WANTED_CITY  = /warszaw|warsaw/i;
const WANTED_SKILL = /react/i;
const CHECK_SKILL  = true;     // the /react category still mixes in other stacks

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');

function decodeState(html) {
    const m = html.match(/<script[^>]*id="serverApp-state"[^>]*>([\s\S]*?)<\/script>/);
    if (!m) return null;
    // Angular escapes the JSON with &q; &a; &l; &g; &s;
    const json = m[1].replace(/&q;/g, '"').replace(/&a;/g, '&')
                     .replace(/&l;/g, '<').replace(/&g;/g, '>').replace(/&s;/g, "'");
    try { return JSON.parse(json); } catch (e) { return null; }
}

function findPostings(state) {
    for (const v of Object.values(state)) {
        const o = v && v.body ? v.body : v;
        if (o && Array.isArray(o.postings) && o.postings.length) return o.postings;
    }
    return null;
}

const state = decodeState(msg.payload || '');
if (!state) {
    node.error('nofluff: serverApp-state not found (status ' + msg.statusCode +
               ', ' + String(msg.payload || '').length + ' bytes)', msg);
    return null;
}

const postings = findPostings(state);
if (!postings) {
    node.error('nofluff: no postings array in state - markup changed', msg);
    return null;
}

function hasSkill(p) {
    return WANTED_SKILL.test(p.technology || '') || WANTED_SKILL.test(p.title || '');
}

function inWarsawOrRemote(p) {
    const places = (p.location && p.location.places) || p.places || [];
    if (p.fullyRemote || (p.location && p.location.fullyRemote)) return true;
    return places.some(pl => WANTED_CITY.test(pl.city || ''));
}

const keep = postings.filter(p => (!CHECK_SKILL || hasSkill(p)) && inWarsawOrRemote(p));
node.status({ fill: 'green', shape: 'dot', text: keep.length + '/' + postings.length + ' kept' });

msg.payload = keep.map(p => ({
    src:       'nofluff',
    id:        p.id,
    sortVal:   p.posted,                      // real publish time, NOT renewed
    key:       norm(p.name) + '|' + norm(p.title),
    title:     p.title,
    company:   p.name,
    seniority: (Array.isArray(p.seniority) ? p.seniority[0] : p.seniority || 'unknown').toLowerCase(),
    remote:    (p.fullyRemote || (p.location && p.location.fullyRemote)) ? 'yes' : 'no',
    url:       'https://nofluffjobs.com/pl/job/' + p.url
}));
return msg;

// Builds the Telegram messages. Fed by store_notify (auto) and tg_command (/send).
const chatId = 8398240851;
const BATCH  = 5;

const queue = flow.get('queued') || [];

if (!queue.length) {
    node.status({ text: 'queue empty' });
    return msg.manual                       // only answer when a human asked
        ? [[{ payload: { chatId, type: 'message', content: 'Nothing new queued.' } }]]
        : null;
}

// group by source so the per-source header still makes sense
const bySrc = {};
queue.forEach(o => { (bySrc[o.src] = bySrc[o.src] || []).push(o); });

const out = [];
for (const src of Object.keys(bySrc).sort()) {
    const offers = bySrc[src];
    for (let i = 0; i < offers.length; i += BATCH) {
        let content = offers.slice(i, i + BATCH)
            .map(o => `🆕 ${o.title}\n${o.company} · ${o.seniority} · ${o.remote === 'yes' ? 'zdalnie' : 'Warszawa'}\n${o.url}`)
            .join('\n\n');
        if (i === 0) {
            content = '---------------------- ' + src + ' ----------------------\n' + content;
        }
        out.push({ payload: { chatId, type: 'message', content } });
    }
}

if (msg.manual) {
    out.unshift({ payload: { chatId, type: 'message', content: `📬 ${queue.length} offer(s) held while muted` } });
}

flow.set('queued', []);
node.status({ fill: 'green', shape: 'dot', text: 'sent ' + queue.length });
return [out];

// Telegram Receiver (output 1) -> this node. Outputs: 1 = flush trigger, 2 = reply
const OWNER = 8398240851;          // only this chat may control the flow

const chatId = msg.payload && msg.payload.chatId;
const text   = String((msg.payload && msg.payload.content) || '').trim().toLowerCase();

// ignore anyone else - the bot username is guessable
if (Number(chatId) !== OWNER) {
    node.warn('ignored command from chatId ' + chatId + ': ' + text);
    return null;
}

const reply  = t => ({ payload: { chatId: chatId, type: 'message', content: t } });
const queued = () => (flow.get('queued') || []).length;
const cmd    = text.split(/\s+/)[0];

if (cmd === '/mute' || cmd === '/pause' || cmd === '/stop') {
    const was = flow.get('paused');
    flow.set('paused', true);
    node.status({ fill: 'grey', shape: 'ring', text: 'muted' });
    return [null, reply(was
        ? `🔕 Already muted. ${queued()} offer(s) waiting.`
        : `🔕 Muted.\nScraping continues - new offers are queued.\n${queued()} waiting.`)];
}

if (cmd === '/resume' || cmd === '/unmute' || cmd === '/start') {
    const was = flow.get('paused');
    const n = queued();
    flow.set('paused', false);
    node.status({ fill: 'green', shape: 'dot', text: 'active' });
    const t = was ? '🔔 Unmuted.' : '🔔 Already active.';
    return n ? [{ manual: true }, reply(`${t}\nDelivering ${n} queued offer(s)...`)]
             : [null, reply(`${t}\nNothing queued.`)];
}

if (cmd === '/send' || cmd === '/flush') {
    const n = queued();
    if (!n) return [null, reply('📭 Nothing queued.')];
    node.status({ text: 'flushing ' + n });
    return [{ manual: true }, reply(`📤 Sending ${n} queued offer(s)...`)];
}

if (cmd === '/status') {
    const store = flow.get('offers') || {};
    const marks = flow.get('marks') || {};
    const state = flow.get('paused') ? '🔕 muted' : '🔔 active';
    const per = {};
    Object.values(store).forEach(o => { per[o.src] = (per[o.src] || 0) + 1; });
    const lines = Object.keys(marks).sort().map(s => `  ${s}: ${per[s] || 0}`);
    return [null, reply(
        `${state}\n${queued()} queued\n${Object.keys(store).length} offers stored\n` +
        lines.join('\n') +
        `\n\nlast run: ${flow.get('lastRun') || 'unknown'}`
    )];
}

return [null, reply(
    `❓ Unknown command "${text}"\n\n` +
    '/mute - hold notifications\n' +
    '/send - deliver what is queued\n' +
    '/resume - unmute and deliver\n' +
    '/status - show state')];

// store_notifications (output 2) / backfill_db -> Supabase upsert request
// Needs env vars SUPABASE_URL and SUPABASE_SECRET_KEY (tab env or the Node-RED process env).
const base = env.get('SUPABASE_URL');
const key  = env.get('SUPABASE_SECRET_KEY');
if (!base || !key) {
    node.status({ fill: 'red', shape: 'ring', text: 'SUPABASE_URL / SUPABASE_SECRET_KEY missing' });
    return null;
}

// Every row must carry exactly the same keys (PostgREST rejects the whole batch otherwise),
// so missing values become null instead of undefined - JSON.stringify drops undefined keys.
const clean = v => (v === undefined || v === null) ? null
                 : (String(v).replace(/\u0000/g, '').trim() || null);

const rows = [];
let skipped = 0;
for (const o of msg.payload || []) {
    const src = clean(o && o.src), id = clean(o && o.id), url = clean(o && o.url);
    if (!src || !id || !url) { skipped++; continue; }
    const t = new Date(o.firstSeen).getTime();
    rows.push({
        src:        src,
        id:         id,
        title:      clean(o.title) || '(no title)',
        company:    clean(o.company),
        seniority:  clean(o.seniority),
        remote:     o.remote === 'yes' || o.remote === true,
        url:        url,
        first_seen: new Date(t > 0 ? t : Date.now()).toISOString()
    });
}
if (skipped) node.warn('to_db: skipped ' + skipped + ' offer(s) without src/id/url');
if (!rows.length) return null;

const headers = {
    apikey: key,
    'Content-Type': 'application/json',
    Prefer: 'resolution=ignore-duplicates,return=minimal'
};
// legacy service_role keys are JWTs and also go in Authorization; new sb_secret_ keys must not
if (key.startsWith('eyJ')) headers.Authorization = 'Bearer ' + key;

// accept both https://x.supabase.co and the dashboard's https://x.supabase.co/rest/v1/
const url = base.replace(/\/+$/, '').replace(/\/rest\/v1$/, '') + '/rest/v1/offers?on_conflict=src,id';

msg.method  = 'POST';
msg.url     = url;
msg.headers = headers;
msg.payload = rows;
msg.dbRows  = rows.length;
msg.dbReq   = { url, headers, body: rows };   // kept so check_db can resend on a transient error
msg.dbTry   = 0;
return msg;

// write_db -> surface failures, retry transient ones; Supabase answers 201 on success
// output 1 is wired back into write_db for retries
const code = msg.statusCode;
const body = String(msg.payload || '');

if (code >= 200 && code < 300) {
    node.status({ fill: 'green', shape: 'dot', text: `saved ${msg.dbRows} @ ${new Date().toLocaleTimeString()}` });
    return null;
}

// network errors (statusCode is e.g. "ECONNRESET"), 5xx, rate limits and Supabase's
// "JWT issued at future" clock-skew 401 are worth another go; anything else is a real bug
const transient = typeof code !== 'number' || code >= 500 || code === 429 ||
                  (code === 401 && body.includes('PGRST303'));
const tries = msg.dbTry || 0;

if (transient && msg.dbReq && tries < 3) {
    const r = msg.dbReq;
    const wait = 5000 * (tries + 1);
    node.status({ fill: 'yellow', shape: 'ring', text: `retry ${tries + 1}/3 in ${wait / 1000}s (${code})` });
    setTimeout(() => node.send({
        method: 'POST', url: r.url, headers: r.headers, payload: r.body,
        dbReq: r, dbRows: msg.dbRows, dbTry: tries + 1
    }), wait);
    return null;
}

node.status({ fill: 'red', shape: 'ring', text: 'db error ' + (code || '?') });
node.error('supabase: status ' + code + (tries ? ' after ' + tries + ' retries' : '') + ': ' + body.slice(0, 500), msg);
return null;

// one-off: push every offer already held in flow context to the database.
// Safe to click again - rows already in the table are ignored.
const CHUNK = 500;

// older entries may predate some fields; the store key is always "src:id", so fill from it
const all = Object.entries(flow.get('offers') || {}).map(([ref, o]) => {
    const i = ref.indexOf(':');
    return Object.assign({}, o, {
        src: (o && o.src) || ref.slice(0, i),
        id:  (o && o.id !== undefined && o.id !== null) ? o.id : ref.slice(i + 1)
    });
});

// one request every 2 s instead of all at once
const chunks = Math.ceil(all.length / CHUNK);
for (let c = 0; c < chunks; c++) {
    setTimeout(() => node.send({ payload: all.slice(c * CHUNK, (c + 1) * CHUNK) }), c * 2000);
}
node.status({ text: `sending ${all.length} in ${chunks} chunk(s)` });
return null;
